/* blinkwired-glass v2
   Authentik 2026.8 — native CSS
   Glass Login Card + restrained UI motion
*/

:root {
  --bw-accent: #43ddc1;
  --bw-accent-hover: #6cebd5;
  --bw-text: #f0faf7;
  --bw-muted: #a9c0ba;
  --bw-ease-out: cubic-bezier(.22, 1, .36, 1);
  --bw-ease-in-out: cubic-bezier(.65, 0, .35, 1);

  --ak-c-login--MaxWidth: 31rem;
  --ak-c-login__main--BackgroundColor: #101b19;
  --ak-c-login__main--Color: var(--bw-text);
  --ak-c-login__main--BoxShadow:
    0 32px 85px rgba(0, 0, 0, .62);
}

/* Inherited colors for Authentik components */
ak-flow-executor {
  color-scheme: dark;

  --pf-global--primary-color--100: #43ddc1;
  --pf-global--primary-color--200: #29b89f;
  --pf-global--Color--100: #edf9f6;
  --pf-global--Color--200: #a9c0ba;

  --ak-c-login--MaxWidth: 31rem;
  --ak-c-login__main--Color: #f0faf7;
}

/* Dark atmospheric canvas */
body:has(ak-flow-executor) {
  background: #020606 !important;
}

ak-flow-executor::part(login) {
  background:
    radial-gradient(
      ellipse 50% 55% at 8% 12%,
      rgba(33, 184, 156, .15),
      transparent 76%
    ),
    radial-gradient(
      ellipse 35% 45% at 92% 88%,
      rgba(16, 110, 98, .09),
      transparent 80%
    ),
    #020606 !important;
}

/* Main glass login card */
ak-flow-executor::part(main) {
  background:
    radial-gradient(
      ellipse at 0% 0%,
      rgba(68, 225, 194, .22),
      transparent 52%
    ),
    linear-gradient(
      145deg,
      rgba(28, 48, 44, .93),
      rgba(9, 17, 16, .96) 62%,
      rgba(13, 25, 23, .94)
    ) !important;

  color: #f0faf7 !important;

  border: 1px solid rgba(113, 233, 204, .22);
  border-radius: 30px;

  backdrop-filter: blur(28px) saturate(140%);
  -webkit-backdrop-filter: blur(28px) saturate(140%);

  box-shadow:
    inset 0 1px 0 rgba(185, 255, 232, .17),
    inset 1px 0 0 rgba(99, 216, 186, .06),
    0 32px 90px rgba(0, 0, 0, .62),
    0 0 75px rgba(36, 193, 161, .10) !important;

  animation:
    bw-card-enter 320ms var(--bw-ease-out) both;

  transition:
    border-color 180ms var(--bw-ease-in-out),
    box-shadow 220ms var(--bw-ease-in-out);
}

ak-flow-executor::part(main):hover {
  border-color: rgba(120, 239, 209, .35);
}

ak-flow-executor::part(main):focus-within {
  border-color: rgba(120, 239, 209, .48);
  box-shadow:
    inset 0 1px 0 rgba(185, 255, 232, .20),
    0 32px 90px rgba(0, 0, 0, .62),
    0 0 85px rgba(36, 193, 161, .15) !important;
}

/* Stagger the exposed flow sections */
ak-flow-executor::part(branding) {
  animation:
    bw-content-enter 320ms var(--bw-ease-out) 35ms both;
}

ak-flow-executor::part(challenge) {
  animation:
    bw-content-enter 300ms var(--bw-ease-out) 65ms both;
}

ak-flow-executor::part(footer) {
  animation:
    bw-content-enter 280ms var(--bw-ease-out) 95ms both;
}

/* Button motion on accessible/light-DOM controls */
ak-flow-executor button,
ak-flow-executor .pf-c-button {
  transition:
    transform 110ms var(--bw-ease-out),
    background-color 180ms var(--bw-ease-in-out),
    box-shadow 180ms var(--bw-ease-in-out);
}

ak-flow-executor button:active,
ak-flow-executor .pf-c-button:active {
  transform: scale(.97);
}

/* Card entrance with subtle mask reveal */
@keyframes bw-card-enter {
  from {
    opacity: 0;
    transform: translateY(16px) scale(.98);
    filter: blur(5px);
    clip-path: inset(5% 0 0 0 round 30px);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
    filter: blur(0);
    clip-path: inset(0 round 30px);
  }
}

@keyframes bw-content-enter {
  from {
    opacity: 0;
    transform: translateY(9px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Mobile */
@media (max-width: 560px) {
  ak-flow-executor::part(main) {
    border-radius: 22px;
    max-width: calc(100vw - 20px);
    margin-inline: auto;
  }
}

/* Accessibility */
@media (prefers-reduced-motion: reduce) {
  ak-flow-executor::part(main),
  ak-flow-executor::part(branding),
  ak-flow-executor::part(challenge),
  ak-flow-executor::part(footer) {
    animation: none !important;
    transition: none !important;
  }

  ak-flow-executor button,
  ak-flow-executor .pf-c-button {
    transition: none !important;
  }
}
